function sha256File(filePath) {
  return crypto.createHash('sha256').update(fs.readFileSync(filePath)).digest('hex');
}

function normalizeRepoPath(p) {
  return String(p).replace(/\\/g, '/').replace(/^\.\/+/, '');
}

function safeRepoPath(p) {
  const normalized = normalizeRepoPath(p);
  const absolute = path.resolve(repoRoot, normalized);
  const relative = path.relative(repoRoot, absolute);
  if (!relative || relative.startsWith('..') || path.isAbsolute(relative)) throw new Error(`Unsafe repository path: ${p}`);
  return { normalized, absolute };
}

function addManifestFile({ archivePath, sourcePath, entry, generated = false, description, category, authority }) {
  const absolute = path.join(packetDir, archivePath);
  const stat = fs.statSync(absolute);
  files.push({
    archive_path: normalizeRepoPath(archivePath),
    source_path: sourcePath,
    entry_id: entry?.id || null,
    category: category || entry?.category || 'generated',
    description: description || entry?.description || '',
    authority: authority || entry?.authority || 'unspecified',
    size_bytes: stat.size,
    sha256: sha256File(absolute),
    generated
  });
}

function copyFile(sourceAbs, sourceRel, archiveRel, entry) {
  const dest = path.join(packetDir, archiveRel);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.copyFileSync(sourceAbs, dest);
  addManifestFile({ archivePath: archiveRel, sourcePath: sourceRel, entry });
}

function copyEntry(entry) {
  const safe = safeRepoPath(entry.path);
  if (!fs.existsSync(safe.absolute)) throw new Error(`Configured historical-audit source does not exist: ${entry.path}`);
  const stat = fs.statSync(safe.absolute);
  if (entry.kind === 'file') {
    if (!stat.isFile()) throw new Error(`Expected file for ${entry.id}: ${entry.path}`);
    copyFile(safe.absolute, safe.normalized, `repo/${safe.normalized}`, entry);
    return;
  }
  if (entry.kind !== 'directory') throw new Error(`Unsupported entry kind ${entry.kind} for ${entry.id}`);
  if (!stat.isDirectory()) throw new Error(`Expected directory for ${entry.id}: ${entry.path}`);
  const stack = [safe.absolute];
  while (stack.length) {
    const dir = stack.pop();
    for (const dirent of fs.readdirSync(dir, { withFileTypes: true })) {
      const absolute = path.join(dir, dirent.name);
      if (dirent.isDirectory()) stack.push(absolute);
      else if (dirent.isFile()) {
        const sourceRel = normalizeRepoPath(path.relative(repoRoot, absolute));
        copyFile(absolute, sourceRel, `repo/${sourceRel}`, entry);
      }
    }
  }
}

function writeGenerated(archiveRel, content, metadata) {
  const dest = path.join(packetDir, archiveRel);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, content.endsWith('\n') ? content : content + '\n');
  addManifestFile({ archivePath: archiveRel, sourcePath: metadata.sourcePath || null, generated: true, ...metadata });
}

fs.rmSync(packetDir, { recursive: true, force: true });
fs.mkdirSync(packetDir, { recursive: true });

for (const id of selectedIds) {
  const entry = entryById.get(id);
  if (!entry) throw new Error(`Unknown historical-audit entry_id: ${id}`);
  if (id === 'persisted_nonce_runs' && runNonces.length) continue;
  copyEntry(entry);
}

const runEntry = entryById.get('persisted_nonce_runs');
for (const runNonce of runNonces) {
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(runNonce)) throw new Error(`Invalid Supervisor run nonce: ${runNonce}`);
  const runPath = `ChatMachines/GeminiSupervisor/runs/${runNonce}`;
  const synthetic = { ...runEntry, id: `persisted_nonce_run:${runNonce}`, path: runPath, kind: 'directory' };
  copyEntry(synthetic);
}

fs.mkdirSync(path.join(packetDir, 'metadata'), { recursive: true });
fs.copyFileSync(sourceMapPath, path.join(packetDir, 'metadata', 'historical-audit-data.json'));
addManifestFile({
  archivePath: 'metadata/historical-audit-data.json',
  sourcePath: sourceMapPath,
  generated: false,
  category: 'evidence_routing_metadata',
  description: 'Exact historical-audit source map used to construct this packet, including descriptions and authority guidance.',
  authority: 'routing_metadata'
});
fs.copyFileSync(triggerPath, path.join(packetDir, 'metadata', 'historical-audit-trigger.json'));
addManifestFile({
  archivePath: 'metadata/historical-audit-trigger.json',
  sourcePath: triggerPath,
  generated: false,
  category: 'audit_request_metadata',
  description: 'Exact trigger/request and archive selection used for this historical-audit run.',
  authority: 'run_request'
});

const lineagePaths = [sourceMap.archive_policy.include_predecessor_path, sourceMap.archive_policy.current_path].filter(Boolean);
const lineageLog = execFileSync('git', [
  'log', '--reverse', '--date=iso-strict', '--format=fuller', '--name-status', '-M', '-C', '--', ...lineagePaths
], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
writeGenerated('generated/git/live-supervisor-lineage.log', lineageLog, {
  category: 'generated_raw_git_history',
  description: 'Fresh complete Git lineage for the Supervisor and predecessor paths at the workflow checkout, generated directly from Git with rename/copy detection.',
  authority: 'primary_git_history'
});

for (const id of selectedIds) {
  const entry = entryById.get(id);
  if (!entry?.include_git_history) continue;
  const safe = safeRepoPath(entry.path);
  const history = execFileSync('git', [
    'log', '--reverse', '--date=iso-strict', '--format=fuller', '--stat', '-p', '--', safe.normalized
  ], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
  writeGenerated(`generated/git/by-entry/${id}.patch.log`, history, {
    sourcePath: safe.normalized,
    category: 'generated_file_history',
    description: `Fresh path-scoped chronological Git history with patches for ${id}: ${entry.description}`,
    authority: 'primary_git_history'
  });
}

files.sort((a, b) => a.archive_path.localeCompare(b.archive_path));
const totalBytes = files.reduce((sum, file) => sum + file.size_bytes, 0);
if (totalBytes > maxPacketBytes) {
  throw new Error(`Historical audit packet is ${totalBytes} bytes, exceeding configured max_evaluator_packet_bytes ${maxPacketBytes}.`);
}

const head = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
const manifest = {
  archive_version: 1,
  generated_at: new Date().toISOString(),
  source_commit_sha: head,
  source_map_path: sourceMapPath,
  trigger_path: triggerPath,
  selected_entry_ids: selectedIds,
  selected_supervisor_run_nonces: runNonces,
  evidence_precedence_guidance: sourceMap.evidence_precedence_guidance,
  total_files: files.length,
  total_uncompressed_bytes: totalBytes,
  files
};
fs.writeFileSync(path.join(packetDir, 'archive-manifest.json'), JSON.stringify(manifest, null, 2) + '\n');
console.log(JSON.stringify({ packet_dir: packetDir, total_files: files.length, total_uncompressed_bytes: totalBytes }, null, 2));

const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const root = __dirname;
const triggerPath = path.resolve(process.env.HISTORICAL_AUDIT_TRIGGER || path.join(root, 'historical-audit-nextmessage', 'nextmessage.json'));
const packetRoot = path.resolve(process.env.HISTORICAL_AUDIT_PACKET_ROOT || path.join(root, '.historical-audit-packet'));
const segmentManifestPath = path.resolve(process.env.HISTORICAL_AUDIT_SEGMENT_MANIFEST || path.join(packetRoot, 'segment-manifest.json'));
const policyPath = path.resolve(process.env.HISTORICAL_AUDIT_SEGMENTATION_POLICY || path.join(root, 'historical-audit-segmentation-policy.json'));
const workerPath = path.join(root, 'historical-audit-fresh-worker.js');

function readJson(p) {
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

function writeJson(p, value) {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, JSON.stringify(value, null, 2) + '\n');
}

function byteSize(value) {
  return Buffer.byteLength(JSON.stringify(value), 'utf8');
}

function sanitizeId(value) {
  return String(value).replace(/[^A-Za-z0-9._-]+/g, '_');
}

function safePacketPath(relativePath) {
  const normalized = String(relativePath).replace(/\\/g, '/').replace(/^\.\/+/, '');
  if (normalized.startsWith('/') || normalized.includes('../')) throw new Error(`Unsafe packet path: ${relativePath}`);
  const absolute = path.resolve(packetRoot, normalized);
  const relative = path.relative(packetRoot, absolute);
  if (!relative || relative.startsWith('..') || path.isAbsolute(relative)) throw new Error(`Packet path escapes root: ${relativePath}`);
  return absolute;
}

function runFreshWorker(mode, inputObject, inputPath, outputPath) {
  writeJson(inputPath, inputObject);
  const child = spawnSync(process.execPath, [workerPath, mode, inputPath, outputPath], {
    cwd: root,
    env: { ...process.env },
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024
  });
  if (child.stdout) process.stdout.write(child.stdout);
  if (child.stderr) process.stderr.write(child.stderr);
  if (child.status !== 0) throw new Error(`Fresh ${mode} evaluator process failed with exit ${child.status}.`);
  return readJson(outputPath);
}

function batchBytes(batch, segmentById) {
  return batch.segment_ids.reduce((sum, id) => sum + Number(segmentById.get(id).size_bytes || 0), 0);
}

function validatePlan(plan, segmentManifest, policy) {
  if (plan.response_type !== 'historical_audit_batch_plan') throw new Error('Planner returned wrong response_type.');
  if (!Array.isArray(plan.primary_batches) || plan.primary_batches.length === 0) throw new Error('Planner must return primary_batches.');
  if (!Array.isArray(plan.crosscheck_batches)) throw new Error('Planner must return crosscheck_batches array.');

  const segments = segmentManifest.segments;
  const segmentById = new Map(segments.map(segment => [segment.segment_id, segment]));
  const expected = new Set(segmentById.keys());
  const counts = new Map([...expected].map(id => [id, 0]));
  const batchIds = new Set();

  const targetPrimary = Number(policy.heuristic.target_primary_batch_bytes);
  const hardPrimary = Number(policy.heuristic.hard_max_primary_batch_bytes);
  const hardCrosscheck = Number(policy.heuristic.hard_max_crosscheck_batch_bytes);
  const corpusBytes = Number(segmentManifest.corpus_bytes);
  const minPrimaryCount = Math.ceil(corpusBytes / targetPrimary);

  if (plan.primary_batches.length < minPrimaryCount) {
    throw new Error(`Planner produced ${plan.primary_batches.length} primary batches; heuristic requires at least ${minPrimaryCount}.`);
  }

  for (const batch of plan.primary_batches) {
    if (!batch || typeof batch !== 'object') throw new Error('Every primary batch must be an object.');
    if (typeof batch.batch_id !== 'string' || !batch.batch_id.trim()) throw new Error('Every primary batch requires batch_id.');
    if (batchIds.has(batch.batch_id)) throw new Error(`Duplicate batch_id ${batch.batch_id}.`);
    batchIds.add(batch.batch_id);
    if (!Array.isArray(batch.segment_ids) || batch.segment_ids.length === 0) throw new Error(`${batch.batch_id} requires segment_ids.`);
    const local = new Set();
    for (const id of batch.segment_ids) {
      if (!expected.has(id)) throw new Error(`${batch.batch_id} references unknown segment ${id}.`);
      if (local.has(id)) throw new Error(`${batch.batch_id} duplicates segment ${id} within the batch.`);
      local.add(id);
      counts.set(id, counts.get(id) + 1);
    }
    batch.context_bytes = batchBytes(batch, segmentById);
    if (batch.context_bytes > hardPrimary) throw new Error(`${batch.batch_id} is ${batch.context_bytes} bytes; hard primary limit is ${hardPrimary}.`);
    if (typeof batch.grouping_rationale !== 'string' || !batch.grouping_rationale.trim()) throw new Error(`${batch.batch_id} requires grouping_rationale.`);
  }

  const missing = [];
  const duplicated = [];
  for (const [id, count] of counts.entries()) {
    if (count === 0) missing.push(id);
    if (count > 1) duplicated.push(id);
  }
  if (missing.length) throw new Error(`Primary batches omitted segments: ${missing.join(', ')}`);
  if (duplicated.length) throw new Error(`Primary batches duplicated segments: ${duplicated.join(', ')}`);

  if (policy.batch_constraints.at_least_one_crosscheck_batch && plan.crosscheck_batches.length === 0) {
    throw new Error('At least one crosscheck batch is required by policy.');
  }

  let crosscheckBytes = 0;
  for (const batch of plan.crosscheck_batches) {
    if (!batch || typeof batch !== 'object') throw new Error('Every crosscheck batch must be an object.');
    if (typeof batch.batch_id !== 'string' || !batch.batch_id.trim()) throw new Error('Every crosscheck batch requires batch_id.');
    if (batchIds.has(batch.batch_id)) throw new Error(`Duplicate batch_id ${batch.batch_id}.`);
    batchIds.add(batch.batch_id);
    if (!Array.isArray(batch.segment_ids) || batch.segment_ids.length === 0) throw new Error(`${batch.batch_id} requires segment_ids.`);
    const local = new Set();
    for (const id of batch.segment_ids) {
      if (!expected.has(id)) throw new Error(`${batch.batch_id} references unknown segment ${id}.`);
      if (local.has(id)) throw new Error(`${batch.batch_id} duplicates segment ${id} within the batch.`);
      local.add(id);
    }
    batch.context_bytes = batchBytes(batch, segmentById);
    if (batch.context_bytes > hardCrosscheck) throw new Error(`${batch.batch_id} is ${batch.context_bytes} bytes; hard crosscheck limit is ${hardCrosscheck}.`);
    crosscheckBytes += batch.context_bytes;
    if (typeof batch.crosscheck_rationale !== 'string' || !batch.crosscheck_rationale.trim()) throw new Error(`${batch.batch_id} requires crosscheck_rationale.`);
    if (batch.selection_method === 'stochastic' && (typeof batch.seed !== 'string' || !batch.seed.trim())) {
      throw new Error(`${batch.batch_id} uses stochastic selection but has no seed.`);
    }
  }

  const maxCrosscheckBytes = Math.floor(corpusBytes * Number(policy.batch_constraints.maximum_crosscheck_raw_fraction));
  const totalAssignedBytes = corpusBytes + crosscheckBytes;
  const maxAssignedBytes = Math.floor(corpusBytes * Number(policy.batch_constraints.maximum_total_raw_assignment_multiplier));
  if (crosscheckBytes > maxCrosscheckBytes) throw new Error(`Crosscheck raw bytes ${crosscheckBytes} exceed budget ${maxCrosscheckBytes}.`);
  if (totalAssignedBytes > maxAssignedBytes) throw new Error(`Total raw assignment ${totalAssignedBytes} exceeds 1.5x corpus budget ${maxAssignedBytes}.`);

  return {
    corpus_bytes: corpusBytes,
    primary_batch_count: plan.primary_batches.length,
    minimum_primary_batch_count: minPrimaryCount,
    primary_raw_bytes: corpusBytes,
    crosscheck_batch_count: plan.crosscheck_batches.length,
    crosscheck_raw_bytes: crosscheckBytes,
    total_assigned_raw_bytes: totalAssignedBytes,
    maximum_total_raw_assignment_bytes: maxAssignedBytes,
    raw_assignment_multiplier: totalAssignedBytes / corpusBytes,
    complete_primary_coverage: true,
    primary_duplication: false
  };
}

function materializeBatch(batch, batchType, taskText, segmentById) {
  return {
    audit_task: taskText,
    batch: {
      batch_id: batch.batch_id,
      batch_type: batchType,
      purpose: batch.purpose || '',
      grouping_rationale: batch.grouping_rationale || null,
      crosscheck_rationale: batch.crosscheck_rationale || null,
      selection_method: batch.selection_method || null,
      seed: batch.seed || null,
      context_bytes: batch.context_bytes
    },
    segments: batch.segment_ids.map(id => {
      const metadata = segmentById.get(id);
      return {
        metadata,
        content: fs.readFileSync(safePacketPath(metadata.segment_path), 'utf8')
      };
    })
  };
}

function balanceResultsIntoFour(items) {
  const groups = [0, 1, 2, 3].map(index => ({ quarter: index + 1, total_bytes: 0, items: [] }));
  const sorted = [...items].sort((a, b) => b.result_bytes - a.result_bytes || a.batch_id.localeCompare(b.batch_id));
  for (const item of sorted) {
    groups.sort((a, b) => a.total_bytes - b.total_bytes || a.quarter - b.quarter);
    groups[0].items.push(item);
    groups[0].total_bytes += item.result_bytes;
  }
  return groups.sort((a, b) => a.quarter - b.quarter);
}

function updateProcessView(runRoot, patch) {
  const viewPath = path.join(runRoot, 'live-view', 'process-view.json');
  let current = {};
  try { current = readJson(viewPath); } catch (_) {}
  writeJson(viewPath, {
    ...current,
    observer: 'flat_batch_audit_orchestrator',
    execution_host: 'GitHub Actions Node',
    recursive_model_calling: false,
    fresh_process_per_evaluator: true,
    ...patch,
    updated_at: new Date().toISOString()
  });
}

function main() {
  const trigger = readJson(triggerPath);
  const segmentManifest = readJson(segmentManifestPath);
  const policy = readJson(policyPath);
  const runNonce = String(trigger.run_nonce || '').trim();
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(runNonce)) throw new Error(`Invalid run_nonce: ${runNonce}`);
  const taskText = trigger.nextmessage?.parts?.map(part => part.text || '').join('\n').trim();
  if (!taskText) throw new Error('Audit task text is missing.');

  const runRoot = path.join(root, 'evaluations', runNonce);
  const workRoot = path.join(runRoot, 'flat-work');
  const batchResultRoot = path.join(runRoot, 'batch-results');
  const synthesisRoot = path.join(runRoot, 'synthesis');
  fs.mkdirSync(workRoot, { recursive: true });
  fs.mkdirSync(batchResultRoot, { recursive: true });
  fs.mkdirSync(synthesisRoot, { recursive: true });

  updateProcessView(runRoot, { phase: 'planner', status: 'running' });

  const plannerInput = {
    audit_task: taskText,
    segmentation_policy: policy,
    segment_manifest: {
      corpus_bytes: segmentManifest.corpus_bytes,
      segment_count: segmentManifest.segment_count,
      maximum_total_raw_assignment_bytes: segmentManifest.maximum_total_raw_assignment_bytes,
      maximum_crosscheck_raw_bytes: segmentManifest.maximum_crosscheck_raw_bytes,
      segments: segmentManifest.segments.map(segment => ({
        segment_id: segment.segment_id,
        source_archive_path: segment.source_archive_path,
        source_path: segment.source_path,
        entry_id: segment.entry_id,
        category: segment.category,
        authority: segment.authority,
        description: segment.description,
        start_line: segment.start_line,
        end_line: segment.end_line,
        size_bytes: segment.size_bytes,
        boundary_after: segment.boundary_after
      }))
    }
  };

  const plannerPath = path.join(runRoot, 'batch-plan.json');
  const plan = runFreshWorker('planner', plannerInput, path.join(workRoot, 'planner-input.json'), plannerPath);
  const validation = validatePlan(plan, segmentManifest, policy);
  writeJson(path.join(runRoot, 'batch-plan-validation.json'), validation);

  const segmentById = new Map(segmentManifest.segments.map(segment => [segment.segment_id, segment]));
  const allBatches = [
    ...plan.primary_batches.map(batch => ({ ...batch, batch_type: 'primary' })),
    ...plan.crosscheck_batches.map(batch => ({ ...batch, batch_type: 'crosscheck' }))
  ];

  const compactResults = [];
  let completed = 0;
  for (const batch of allBatches) {
    updateProcessView(runRoot, {
      phase: batch.batch_type === 'primary' ? 'primary_batches' : 'crosscheck_batches',
      current_batch_id: batch.batch_id,
      completed_batch_count: completed,
      total_batch_count: allBatches.length,
      status: 'running'
    });
    const safeId = sanitizeId(batch.batch_id);
    const inputPath = path.join(workRoot, `batch-${safeId}-input.json`);
    const outputPath = path.join(batchResultRoot, `${safeId}.json`);
    const batchInput = materializeBatch(batch, batch.batch_type, taskText, segmentById);
    const result = runFreshWorker('batch', batchInput, inputPath, outputPath);
    if (result.batch_id !== batch.batch_id) result.batch_id = batch.batch_id;
    if (!result.batch_type) result.batch_type = batch.batch_type;
    compactResults.push({
      batch_id: batch.batch_id,
      batch_type: batch.batch_type,
      result_path: path.relative(runRoot, outputPath).replace(/\\/g, '/'),
      result_bytes: byteSize(result),
      result
    });
    completed += 1;
  }

  const quarters = balanceResultsIntoFour(compactResults);
  const synthesisTree = {
    version: 1,
    balancing_method: 'greedy_largest_result_first_into_current_smallest_of_four_bins',
    total_batch_result_bytes: compactResults.reduce((sum, item) => sum + item.result_bytes, 0),
    quarters: quarters.map(group => ({
      synthesis_id: `Q${group.quarter}`,
      source_batch_ids: group.items.map(item => item.batch_id),
      source_result_bytes: group.total_bytes
    })),
    dyads: [
      { synthesis_id: 'D1', source_synthesis_ids: ['Q1', 'Q2'] },
      { synthesis_id: 'D2', source_synthesis_ids: ['Q3', 'Q4'] }
    ],
    final: { synthesis_id: 'FINAL', source_synthesis_ids: ['D1', 'D2'] }
  };
  writeJson(path.join(runRoot, 'synthesis-tree.json'), synthesisTree);

  const quarterOutputs = [];
  for (const group of quarters) {
    const synthesisId = `Q${group.quarter}`;
    updateProcessView(runRoot, { phase: 'quarter_synthesis', current_synthesis_id: synthesisId, status: 'running' });
    const input = {
      audit_task: taskText,
      synthesis_id: synthesisId,
      source_batch_ids: group.items.map(item => item.batch_id),
      source_result_bytes: group.total_bytes,
      batch_results: group.items.map(item => item.result)
    };
    const outputPath = path.join(synthesisRoot, `${synthesisId}.json`);
    const output = runFreshWorker('synth_quarter', input, path.join(workRoot, `${synthesisId}-input.json`), outputPath);
    if (!output.synthesis_id) output.synthesis_id = synthesisId;
    quarterOutputs.push(output);
  }

  const dyadSpecs = [
    { id: 'D1', indexes: [0, 1] },
    { id: 'D2', indexes: [2, 3] }
  ];
  const dyadOutputs = [];
  for (const spec of dyadSpecs) {
    updateProcessView(runRoot, { phase: 'dyad_synthesis', current_synthesis_id: spec.id, status: 'running' });
    const source = spec.indexes.map(index => quarterOutputs[index]);
    const input = {
      audit_task: taskText,
      synthesis_id: spec.id,
      source_synthesis_ids: source.map(item => item.synthesis_id),
      quarter_syntheses: source
    };
    const outputPath = path.join(synthesisRoot, `${spec.id}.json`);
    const output = runFreshWorker('synth_dyad', input, path.join(workRoot, `${spec.id}-input.json`), outputPath);
    if (!output.synthesis_id) output.synthesis_id = spec.id;
    dyadOutputs.push(output);
  }

  updateProcessView(runRoot, { phase: 'final_synthesis', current_synthesis_id: 'FINAL', status: 'running' });
  const finalInput = {
    audit_task: taskText,
    synthesis_id: 'FINAL',
    validated_raw_context_budget: validation,
    synthesis_tree: synthesisTree,
    dyad_syntheses: dyadOutputs
  };
  const finalPath = path.join(runRoot, 'evaluation.json');
  const finalResult = runFreshWorker('synth_final', finalInput, path.join(workRoot, 'FINAL-input.json'), finalPath);

  writeJson(path.join(runRoot, 'run-metadata.json'), {
    run_nonce: runNonce,
    execution_architecture: 'flat batches -> four quarter syntheses -> two dyad syntheses -> final synthesis',
    recursive_model_calling: false,
    fresh_process_per_evaluator: true,
    primary_batch_count: plan.primary_batches.length,
    crosscheck_batch_count: plan.crosscheck_batches.length,
    raw_context_budget: validation,
    synthesis_tree_path: 'synthesis-tree.json',
    completed_at: new Date().toISOString()
  });

  updateProcessView(runRoot, {
    phase: 'complete',
    status: 'complete',
    current_batch_id: null,
    current_synthesis_id: null,
    completed_batch_count: allBatches.length,
    total_batch_count: allBatches.length,
    final_evaluation_available: true
  });

  console.log(JSON.stringify({
    run_nonce: runNonce,
    primary_batches: plan.primary_batches.length,
    crosscheck_batches: plan.crosscheck_batches.length,
    raw_assignment_multiplier: validation.raw_assignment_multiplier,
    quarter_syntheses: 4,
    dyad_syntheses: 2,
    final_output: finalPath,
    response_type: finalResult.response_type
  }, null, 2));
}

try {
  main();
} catch (error) {
  try {
    const trigger = readJson(triggerPath);
    const runNonce = String(trigger.run_nonce || '').trim();
    if (/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(runNonce)) {
      updateProcessView(path.join(root, 'evaluations', runNonce), { phase: 'failed', status: 'failed', error: error.message });
    }
  } catch (_) {}
  console.error(error);
  process.exitCode = 1;
}

const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');

const [packetRootArg, policyPathArg] = process.argv.slice(2);
if (!packetRootArg || !policyPathArg) {
  throw new Error('Usage: node historical-audit-segmenter.js <packet-root> <segmentation-policy>');
}

const packetRoot = path.resolve(packetRootArg);
const policyPath = path.resolve(policyPathArg);
const policy = JSON.parse(fs.readFileSync(policyPath, 'utf8'));
const archiveManifest = JSON.parse(fs.readFileSync(path.join(packetRoot, 'archive-manifest.json'), 'utf8'));
const targetBytes = Number(policy.heuristic.target_segment_bytes);
const hardMaxBytes = Number(policy.heuristic.hard_max_segment_bytes);
if (!(targetBytes > 0) || !(hardMaxBytes >= targetBytes)) throw new Error('Invalid segmentation byte policy.');

const segmentRoot = path.join(packetRoot, 'segments');
fs.rmSync(segmentRoot, { recursive: true, force: true });
fs.mkdirSync(segmentRoot, { recursive: true });

function sha256(text) {
  return crypto.createHash('sha256').update(text).digest('hex');
}

function safeArchivePath(archivePath) {
  const normalized = String(archivePath).replace(/\\/g, '/').replace(/^\.\/+/, '');
  if (normalized.startsWith('/') || normalized.includes('../')) throw new Error(`Unsafe archive path: ${archivePath}`);
  const absolute = path.resolve(packetRoot, normalized);
  const relative = path.relative(packetRoot, absolute);
  if (!relative || relative.startsWith('..') || path.isAbsolute(relative)) throw new Error(`Archive path escapes packet root: ${archivePath}`);
  return absolute;
}

function charEndWithinBytes(text, start, maxBytes) {
  let low = start + 1;
  let high = text.length;
  let best = Math.min(text.length, start + 1);
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    const bytes = Buffer.byteLength(text.slice(start, mid), 'utf8');
    if (bytes <= maxBytes) {
      best = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return best;
}

function chooseBoundary(text, start) {
  if (start >= text.length) return { end: start, boundary: 'eof' };
  const targetEnd = charEndWithinBytes(text, start, targetBytes);
  if (targetEnd >= text.length) return { end: text.length, boundary: 'eof' };
  const hardEnd = charEndWithinBytes(text, start, hardMaxBytes);
  const minBytes = Math.floor(targetBytes * 0.55);
  const minEnd = charEndWithinBytes(text, start, minBytes);
  const window = text.slice(start, hardEnd);
  const targetRelative = Math.max(0, targetEnd - start);
  const minRelative = Math.max(0, minEnd - start);

  const candidates = [
    { token: '\ncommit ', name: 'git_commit_boundary' },
    { token: '\n## ', name: 'markdown_heading_boundary' },
    { token: '\n# ', name: 'markdown_heading_boundary' },
    { token: '\n\n', name: 'paragraph_boundary' },
    { token: '\n', name: 'line_boundary' }
  ];

  for (const candidate of candidates) {
    let idx = window.lastIndexOf(candidate.token, targetRelative);
    if (idx < minRelative) {
      idx = window.indexOf(candidate.token, targetRelative);
      if (idx < 0 || idx + candidate.token.length > hardEnd - start) idx = -1;
    }
    if (idx >= minRelative) {
      const end = start + idx + (candidate.token === '\n' ? 1 : 0);
      if (end > start) return { end, boundary: candidate.name };
    }
  }

  return { end: hardEnd, boundary: 'hard_utf8_byte_boundary' };
}

function lineNumberAt(text, charIndex) {
  let count = 1;
  for (let i = 0; i < charIndex; i += 1) if (text.charCodeAt(i) === 10) count += 1;
  return count;
}

const segments = [];
let sequence = 0;
for (const file of archiveManifest.files) {
  const sourcePath = safeArchivePath(file.archive_path);
  const content = fs.readFileSync(sourcePath, 'utf8');
  let start = 0;
  let byteOffset = 0;
  while (start < content.length) {
    const chosen = chooseBoundary(content, start);
    if (chosen.end <= start) throw new Error(`Segmenter made no progress on ${file.archive_path}.`);
    const slice = content.slice(start, chosen.end);
    const sizeBytes = Buffer.byteLength(slice, 'utf8');
    if (sizeBytes > hardMaxBytes) throw new Error(`Segment exceeds hard max: ${file.archive_path} ${sizeBytes}`);
    sequence += 1;
    const segmentId = `SEG-${String(sequence).padStart(5, '0')}`;
    const segmentRel = `segments/${segmentId}.txt`;
    fs.writeFileSync(path.join(packetRoot, segmentRel), slice);
    const startLine = lineNumberAt(content, start);
    const endLine = startLine + (slice.match(/\n/g) || []).length;
    segments.push({
      segment_id: segmentId,
      segment_path: segmentRel,
      source_archive_path: file.archive_path,
      source_path: file.source_path,
      entry_id: file.entry_id,
      category: file.category,
      authority: file.authority,
      description: file.description,
      start_line: startLine,
      end_line: endLine,
      source_byte_start: byteOffset,
      source_byte_end_exclusive: byteOffset + sizeBytes,
      size_bytes: sizeBytes,
      sha256: sha256(slice),
      boundary_after: chosen.boundary
    });
    byteOffset += sizeBytes;
    start = chosen.end;
  }
}

const corpusBytes = segments.reduce((sum, segment) => sum + segment.size_bytes, 0);
const expectedBytes = archiveManifest.files.reduce((sum, file) => sum + Number(file.size_bytes || 0), 0);
if (corpusBytes !== expectedBytes) throw new Error(`Segment byte coverage mismatch: ${corpusBytes} != ${expectedBytes}`);

const segmentManifest = {
  version: 1,
  generated_at: new Date().toISOString(),
  segmentation_policy: policy,
  archive_source_commit_sha: archiveManifest.source_commit_sha,
  corpus_bytes: corpusBytes,
  segment_count: segments.length,
  segment_target_bytes: targetBytes,
  segment_hard_max_bytes: hardMaxBytes,
  maximum_total_raw_assignment_bytes: Math.floor(corpusBytes * Number(policy.batch_constraints.maximum_total_raw_assignment_multiplier)),
  maximum_crosscheck_raw_bytes: Math.floor(corpusBytes * Number(policy.batch_constraints.maximum_crosscheck_raw_fraction)),
  segments
};

fs.writeFileSync(path.join(packetRoot, 'segment-manifest.json'), JSON.stringify(segmentManifest, null, 2) + '\n');
console.log(JSON.stringify({ corpus_bytes: corpusBytes, segment_count: segments.length, segment_manifest: path.join(packetRoot, 'segment-manifest.json') }, null, 2));

'use strict';

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const repoRoot = path.resolve(__dirname, '../../..');
const readingRoom = path.join(repoRoot, 'ChatMachines/GeminiSupervisor/live-ground-truth/reading-room');
const TASK_ID = 'task_semantic_define_each_array_item';
const ACTIVE_RE = new RegExp(`^${TASK_ID}-([0-9a-f]{40})\\.json$`, 'i');
const apiKey = process.env.GEMINI_API_KEY;
const model = process.env.GEMINI_MODEL;
const BATCH_SIZE = Number(process.env.COMPREHENSION_BATCH_SIZE || 24);
const REQUEST_TIMEOUT_MS = Number(process.env.COMPREHENSION_TIMEOUT_MS || 300000);

if (!apiKey) throw new Error('GEMINI_API_KEY is missing');
if (!model) throw new Error('GEMINI_MODEL is missing');

function findActiveTask() {
  const names = fs.readdirSync(readingRoom).filter(name => ACTIVE_RE.test(name));
  if (names.length !== 1) throw new Error(`Expected exactly one active comprehension task; found ${names.length}`);
  return path.join(readingRoom, names[0]);
}

function resolveRepoFile(relativePath) {
  if (typeof relativePath !== 'string' || relativePath.trim() === '') throw new Error('Expected a non-empty repository-relative filename.');
  const resolved = path.resolve(repoRoot, relativePath);
  const prefix = `${repoRoot}${path.sep}`;
  if (resolved !== repoRoot && !resolved.startsWith(prefix)) throw new Error(`Path escapes repository root: ${relativePath}`);
  return resolved;
}

function terminalNode(value) {
  let node = value;
  while (node !== null && typeof node === 'object') {
    if (Array.isArray(node)) {
      if (node.length !== 1) return node;
      node = node[0];
      continue;
    }
    const keys = Object.keys(node);
    if (keys.length !== 1) return node;
    node = node[keys[0]];
  }
  return node;
}

function terminalIsEmptyContainer(value) {
  const terminal = terminalNode(value);
  if (Array.isArray(terminal)) return terminal.length === 0;
  return terminal !== null && typeof terminal === 'object' && Object.keys(terminal).length === 0;
}

function extractJson(text) {
  const trimmed = text.trim();
  try { return JSON.parse(trimmed); } catch (error) {
    const fenced = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
    if (!fenced) throw error;
    return JSON.parse(fenced[1]);
  }
}

async function callGemini(parts, systemInstruction, maxOutputTokens = 32768) {
  const response = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-goog-api-key': apiKey
      },
      body: JSON.stringify({
        system_instruction: { parts: [{ text: systemInstruction }] },
        contents: [{ role: 'user', parts }],
        generationConfig: {
          temperature: 0,
          responseMimeType: 'application/json',
          maxOutputTokens
        }
      }),
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS)
    }
  );

  const raw = await response.text();
  let body;
  try { body = JSON.parse(raw); } catch (_) {
    throw new Error(`Gemini returned non-JSON HTTP ${response.status}: ${raw.slice(0, 2000)}`);
  }
  if (!response.ok) throw new Error(`Gemini HTTP ${response.status}: ${JSON.stringify(body.error || body)}`);
  const reply = body.candidates?.[0]?.content?.parts?.map(part => part.text || '').join('\n').trim();
  if (!reply) throw new Error(`Gemini returned no text: ${JSON.stringify(body).slice(0, 4000)}`);
  return extractJson(reply);
}

function validDefinitionArray(value, expectedLength) {
  return Array.isArray(value) && value.length === expectedLength && value.every(record => {
    if (record === null || typeof record !== 'object' || Array.isArray(record)) return false;
    const keys = Object.keys(record);
    return keys.length === 1 && keys[0] === 'item' && typeof record.item === 'string' && record.item.trim() !== '';
  });
}

async function defineBatch(batch, filename, batchNumber, batchCount) {
  const prompt = [
    `Target filename: ${filename}`,
    `Batch ${batchNumber} of ${batchCount}.`,
    'Each INPUT_SIGNATURE below is one non-empty flattened semantic signature from that JSON array.',
    'For every signature, in the exact supplied order, generate its semantic definition in the context of the target filename.',
    'Define what the signature means in the document/task contract, using its path, field name, and terminal value. Do not merely restate JSON syntax.',
    'Return definition only. Each output record must have exactly one key named item and one non-empty string value.',
    `Return JSON only as an array of exactly ${batch.length} records: [{"item":"semantic definition"}, ...].`,
    'Do not add source indexes, source values, categories, confidence, gate fields, commentary, or any other keys.',
    '',
    'INPUT_SIGNATURES:',
    JSON.stringify(batch)
  ].join('\n');

  const system = [
    'You are the semantic-definition worker for a comprehension-task test.',
    'The supplied JSON signatures are authoritative input evidence.',
    'A flattened signature encodes a document path and usually a terminal field/value. Explain the semantic role of that exact signature in context.',
    'Output one definition-only record for every supplied signature, preserving order exactly.',
    'Do not omit, merge, reorder, or add records.'
  ].join(' ');

  for (let attempt = 1; attempt <= 3; attempt++) {
    const result = await callGemini([{ text: prompt }], system, 32768);
    if (validDefinitionArray(result, batch.length)) return result;
    console.error(`[comprehension-agent] batch ${batchNumber} shape validation failed, attempt ${attempt}`);
  }
  throw new Error(`Gemini could not return a valid definition-only array for batch ${batchNumber}`);
}

function writeGzip(relativePath, value) {
  const absolute = resolveRepoFile(relativePath);
  fs.mkdirSync(path.dirname(absolute), { recursive: true });
  const bytes = Buffer.from(JSON.stringify(value), 'utf8');
  fs.writeFileSync(absolute, zlib.gzipSync(bytes, { level: 9 }));
}

async function main() {
  const activePath = findActiveTask();
  const task = JSON.parse(fs.readFileSync(activePath, 'utf8'));
  const filename = task?.verify_target_array?.filename;
  const targetPath = resolveRepoFile(filename);
  const source = JSON.parse(fs.readFileSync(targetPath, 'utf8'));
  if (!Array.isArray(source)) throw new Error('Comprehension target must be a top-level JSON array');

  const nonempty = source.filter(item => !terminalIsEmptyContainer(item));
  const expectedCount = nonempty.length;
  const batchCount = Math.ceil(expectedCount / BATCH_SIZE);
  const activeName = path.basename(activePath);
  const commitSha = (activeName.match(ACTIVE_RE) || [])[1];
  if (!commitSha) throw new Error(`Could not derive task instance SHA from ${activeName}`);

  const archiveRoot = `ChatMachines/GeminiSupervisor/live-ground-truth/reading-room/comprehension-task-batches/${commitSha}`;
  const batchArchiveFilenames = [];
  const allRecords = [];

  console.log(`[comprehension-agent] source items=${source.length}; nonempty=${expectedCount}; batches=${batchCount}`);

  for (let offset = 0; offset < expectedCount; offset += BATCH_SIZE) {
    const batchNumber = Math.floor(offset / BATCH_SIZE) + 1;
    const batch = nonempty.slice(offset, offset + BATCH_SIZE);
    console.log(`[comprehension-agent] semantic batch ${batchNumber}/${batchCount} (${batch.length} signatures)`);
    const records = await defineBatch(batch, filename, batchNumber, batchCount);
    allRecords.push(...records);

    const batchRelative = `${archiveRoot}/batch-${String(batchNumber).padStart(4, '0')}.json.gz`;
    writeGzip(batchRelative, records);
    batchArchiveFilenames.push(batchRelative);
  }

  if (!validDefinitionArray(allRecords, expectedCount)) throw new Error('Combined semantic output failed definition-only validation');

  const completeRelative = `${archiveRoot}/complete.json.gz`;
  writeGzip(completeRelative, allRecords);

  task.count_array_nonempty_items.how_many = expectedCount;
  task.doRecord_withReturnSchema.nonempty_items_counted = expectedCount;
  task.doRecord_withReturnSchema.returnSchemaArraySize = expectedCount;
  task.doRecord_withReturnSchema.returnSchemaArray = allRecords;
  task.doRecord_withReturnSchema.batch_archive_filenames = batchArchiveFilenames;
  task.combine_and_send_batch_archives.complete_batch_archive_filename = completeRelative;

  fs.writeFileSync(activePath, `${JSON.stringify(task, null, 2)}\n`, 'utf8');
  console.log(`[comprehension-agent] completed ${expectedCount} definitions; archive=${completeRelative}`);
}

main().catch(error => {
  console.error(`[comprehension-agent] ${error.stack || error.message}`);
  process.exitCode = 1;
});

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { isDeepStrictEqual } = require('util');

const rootDir = path.resolve(__dirname, '../../..');
const supervisorDir = path.join(rootDir, 'ChatMachines/GeminiSupervisor');
const depMapPath = path.join(supervisorDir, 'dependency-map.json');
const runsRoot = path.join(supervisorDir, 'runs');

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function writeJson(filePath, value) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, JSON.stringify(value, null, 2) + '\n', 'utf8');
}

function validateNonce(runNonce) {
  if (typeof runNonce !== 'string' || !/^[A-Za-z0-9_-]+$/.test(runNonce)) {
    throw new Error(`Invalid run_nonce: ${runNonce}`);
  }
  return runNonce;
}

function registryKeys() {
  const map = readJson(depMapPath);
  const registry = map.truth_readable_registry;
  if (!registry || typeof registry !== 'object' || Array.isArray(registry)) {
    throw new Error('dependency-map.json.truth_readable_registry must be an object');
  }
  return Object.keys(registry);
}

function pathsFor(runNonce) {
  const runDir = path.join(runsRoot, validateNonce(runNonce));
  return {
    runDir,
    formPath: path.join(runDir, 'step-0-form.json'),
    lockPath: path.join(runDir, '.step-0-form.lock.json')
  };
}

function generateStep0Form(userRequest, existingNonce = null) {
  const runNonce = validateNonce(existingNonce || `run_${Date.now()}_${crypto.randomBytes(6).toString('hex')}`);
  const { formPath, lockPath } = pathsFor(runNonce);
  if (fs.existsSync(formPath) || fs.existsSync(lockPath)) {
    throw new Error(`Step 0 form already exists for ${runNonce}`);
  }

  const documents = registryKeys();
  const documentSelection = Object.fromEntries(documents.map((docId) => [docId, false]));
  const generatedAt = new Date().toISOString();
  const request = typeof userRequest === 'string' ? userRequest : '';

  const form = {
    start_of_turn: {
      role_required: 'ChatGPT model',
      role_forbidden: 'Gemini model',
      role_completed: '',
      role_verification: {
        method: '',
        evidence: ''
      },
      run_nonce: runNonce,
      user_request: request,
      current_timestamp: generatedAt,
      return_schema_completed_timestamp: '',
      nonce: runNonce,
      task_understanding: '',
      execution_plan: '',
      document_selection: documentSelection,
      return_schema_completed: false
    },
    _form_control: {
      form_version: 1,
      step_number: 0,
      generated_at: generatedAt,
      selectable_document_universe: documents,
      worker_editable_paths: [
        'start_of_turn.role_completed',
        'start_of_turn.role_verification.method',
        'start_of_turn.role_verification.evidence',
        'start_of_turn.return_schema_completed_timestamp',
        'start_of_turn.task_understanding',
        'start_of_turn.execution_plan',
        'start_of_turn.document_selection.*',
        'start_of_turn.return_schema_completed'
      ]
    }
  };

  const lock = {
    form_version: 1,
    step_number: 0,
    run_nonce: runNonce,
    generated_at: generatedAt,
    locked: {
      role_required: form.start_of_turn.role_required,
      role_forbidden: form.start_of_turn.role_forbidden,
      run_nonce: form.start_of_turn.run_nonce,
      user_request: form.start_of_turn.user_request,
      current_timestamp: form.start_of_turn.current_timestamp,
      nonce: form.start_of_turn.nonce,
      selectable_document_universe: documents
    }
  };

  writeJson(formPath, form);
  writeJson(lockPath, lock);
  return { runNonce, formPath, lockPath, form };
}

function validateStep0Form(runNonce) {
  const { formPath, lockPath } = pathsFor(runNonce);
  if (!fs.existsSync(formPath) || !fs.existsSync(lockPath)) {
    throw new Error(`Step 0 form or lock missing for ${runNonce}`);
  }

  const form = readJson(formPath);
  const lock = readJson(lockPath);
  const start = form.start_of_turn;
  if (!start || typeof start !== 'object' || Array.isArray(start)) {
    throw new Error('Step 0 form requires start_of_turn object');
  }

  const expectedLocked = lock.locked;
  const actualLocked = {
    role_required: start.role_required,
    role_forbidden: start.role_forbidden,
    run_nonce: start.run_nonce,
    user_request: start.user_request,
    current_timestamp: start.current_timestamp,
    nonce: start.nonce,
    selectable_document_universe: form?._form_control?.selectable_document_universe
  };
  if (!isDeepStrictEqual(actualLocked, expectedLocked)) {
    throw new Error('Step 0 system-locked fields were modified');
  }

  const expectedDocs = [...expectedLocked.selectable_document_universe].sort();
  const selection = start.document_selection;
  if (!selection || typeof selection !== 'object' || Array.isArray(selection)) {
    throw new Error('start_of_turn.document_selection must be an object');
  }
  const actualDocs = Object.keys(selection).sort();
  if (!isDeepStrictEqual(actualDocs, expectedDocs)) {
    throw new Error('Step 0 document-selection keys changed from the locked document universe');
  }
  for (const [docId, selected] of Object.entries(selection)) {
    if (typeof selected !== 'boolean') throw new Error(`document_selection.${docId} must be boolean`);
  }

  return form;
}

function main() {
  const mode = process.argv[2];
  if (mode === 'validate') {
    validateStep0Form(process.argv[3]);
    console.log(`Step 0 form valid for ${process.argv[3]}`);
    return;
  }
  if (mode === 'generate') {
    const runNonce = process.argv[3] || null;
    const userRequest = process.argv.slice(4).join(' ');
    const result = generateStep0Form(userRequest, runNonce);
    console.log(`Generated Step 0 form for ${result.runNonce}`);
    return;
  }
  throw new Error('Usage: node generate-step-0-form.js [generate <run_nonce> <user request...> | validate <run_nonce>]');
}

if (require.main === module) {
  try {
    main();
  } catch (error) {
    console.error(error.stack || error.message);
    process.exit(1);
  }
}

module.exports = { generateStep0Form, validateStep0Form };

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const sharp = require('sharp');
const { isDeepStrictEqual } = require('util');

const repoRoot = path.resolve(__dirname, '../../..');
const supervisorRoot = path.join(repoRoot, 'ChatMachines/GeminiSupervisor');
const sourcePath = path.join(supervisorRoot, 'Agents.md');
const requestPath = path.join(supervisorRoot, 'live-ground-truth/read-request.json');
const readingRoom = path.join(supervisorRoot, 'live-ground-truth/reading-room');

const DOC_NAME = 'Agents.reader.json';
const VIEWPORT_WIDTH = 1440;
const VIEWPORT_HEIGHT = 900;
const CHARACTER_HEIGHT_PX = 20;
const CONSERVATIVE_CHARACTER_WIDTH_PX = 12;
const PAD_X = 24;
const PAD_Y = 20;
const FONT_SIZE_PX = 20;
const RAW_ROWS = Math.floor((VIEWPORT_HEIGHT - (2 * PAD_Y)) / CHARACTER_HEIGHT_PX);
const ROWS = RAW_ROWS - (RAW_ROWS % 2);
const COLUMNS = Math.floor((VIEWPORT_WIDTH - (2 * PAD_X)) / CONSERVATIVE_CHARACTER_WIDTH_PX);
const CPX = ROWS * COLUMNS;
const INDEX_PREFIX_CHARS = 8;
const CARD_NAME_RE = /^[0-9a-f]{32}\.png$/;
const ACTIVE_RE = /^Agents\.reader\.json-([0-9a-f]{40})$/i;
const manifestRoot = process.env.READING_ROOM_MANIFEST_DIR || path.join(repoRoot, '.live-ground-truth-cache');

function jsonBytes(value) {
  return Buffer.from(JSON.stringify(value), 'utf8');
}

function writeJson(filePath, value) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, jsonBytes(value));
}

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function gitBlobSha(bytes) {
  const header = Buffer.from(`blob ${bytes.length}\0`, 'utf8');
  return crypto.createHash('sha1').update(header).update(bytes).digest('hex');
}

function entryChars(value) {
  return JSON.stringify(value).length + INDEX_PREFIX_CHARS;
}

function splitLineToRenderableItems(text, eol) {
  if (text === '') return [{ type: 'content', text: '', eol }];

  const chunks = [];
  let current = '';
  for (const ch of text) {
    const candidate = current + ch;
    const probe = { type: 'content', text: candidate, eol: '\r\n' };
    if (current && entryChars(probe) > COLUMNS) {
      chunks.push({ type: 'content', text: current, eol: '' });
      current = ch;
    } else {
      current = candidate;
    }
  }
  chunks.push({ type: 'content', text: current, eol });
  return chunks;
}

function projectAgents() {
  const bytes = fs.readFileSync(sourcePath);
  const text = bytes.toString('utf8');
  const items = [];
  const re = /(.*?)(\r\n|\n|\r|$)/g;
  let match;

  while ((match = re.exec(text)) !== null) {
    if (match[0] === '' && re.lastIndex === text.length) break;
    items.push(...splitLineToRenderableItems(match[1], match[2]));
    if (match[2] === '') break;
  }

  // Make the canonical projected array fill complete even-row cards exactly.
  // Splitting preserves document order and bytes: the first fragment has no EOL and
  // the second fragment retains the original EOL. At most ROWS-1 splits are needed.
  const targetItemCount = Math.ceil(items.length / ROWS) * ROWS;
  while (items.length < targetItemCount) {
    let splitIndex = -1;
    let longest = 1;
    for (let i = 0; i < items.length; i++) {
      const length = items[i]?.text?.length || 0;
      if (length > longest) {
        longest = length;
        splitIndex = i;
      }
    }
    if (splitIndex < 0) throw new Error(`Cannot split projected items to ${targetItemCount}`);
    const original = items[splitIndex];
    const midpoint = Math.ceil(original.text.length / 2);
    items.splice(
      splitIndex,
      1,
      { type: 'content', text: original.text.slice(0, midpoint), eol: '' },
      { type: 'content', text: original.text.slice(midpoint), eol: original.eol }
    );
  }

  for (const item of items) {
    if (entryChars(item) > COLUMNS) {
      throw new Error(`Projected item exceeds conservative row width: ${entryChars(item)} > ${COLUMNS}`);
    }
  }

  return {
    doc_id: 'agents',
    canonical_path: 'ChatMachines/GeminiSupervisor/Agents.md',
    source_blob_sha: gitBlobSha(bytes),
    items
  };
}

function validateCommitSha(value) {
  if (!/^[0-9a-f]{40}$/i.test(value || '')) throw new Error(`Invalid commit SHA: ${value}`);
  return value.toLowerCase();
}

function pathsFor(commitSha) {
  const sha = validateCommitSha(commitSha);
  return {
    active: path.join(readingRoom, `${DOC_NAME}-${sha}`),
    failed: path.join(readingRoom, `${DOC_NAME}-${sha}-FAILED`),
    pass: path.join(readingRoom, `${DOC_NAME}-${sha}-PASS`)
  };
}

function randomCardName() {
  return `${crypto.randomBytes(16).toString('hex')}.png`;
}

function shuffle(values) {
  const out = values.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = crypto.randomInt(0, i + 1);
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

function nominalCardCount(values) {
  const totalChars = values.reduce((sum, value) => sum + entryChars(value), 0);
  return Math.max(1, Math.ceil(totalChars / CPX), Math.ceil(values.length / ROWS));
}

function partitionBalanced(values, cardCount, maxItems, costFn = entryChars) {
  const groups = [];
  let cursor = 0;
  const costs = values.map(costFn);
  const suffix = new Array(values.length + 1).fill(0);
  for (let i = values.length - 1; i >= 0; i--) suffix[i] = suffix[i + 1] + costs[i];

  for (let card = 0; card < cardCount; card++) {
    const cardsLeft = cardCount - card;
    const itemsLeft = values.length - cursor;
    if (itemsLeft <= 0) break;

    const minNeededAfter = Math.max(0, cardsLeft - 1);
    const hardMax = Math.min(maxItems, itemsLeft - minNeededAfter);
    const target = suffix[cursor] / cardsLeft;
    const group = [];
    let used = 0;

    while (group.length < hardMax && cursor < values.length) {
      const cost = costs[cursor];
      const mustTake = group.length === 0;
      if (!mustTake && used + cost > target) break;
      group.push(values[cursor]);
      used += cost;
      cursor++;
    }

    if (group.length === 0 && cursor < values.length) group.push(values[cursor++]);
    groups.push(group);
  }

  while (cursor < values.length) {
    const last = groups[groups.length - 1];
    if (!last || last.length >= maxItems) groups.push([]);
    groups[groups.length - 1].push(values[cursor++]);
  }

  return groups;
}

function buildMixedSlots(pairs, orderedParity) {
  const slots = [];
  const placementSlots = [];
  const orderedOnOdd = orderedParity === 'odd';

  for (const pair of pairs) {
    if (orderedOnOdd) {
      slots.push(pair.ordered, pair.shuffled);
      placementSlots.push(false, true);
    } else {
      slots.push(pair.shuffled, pair.ordered);
      placementSlots.push(true, false);
    }
  }

  if (slots.length > ROWS) throw new Error(`Mixed card exceeds ${ROWS} rows`);
  return { slots, placementSlots };
}

function xmlEscape(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function visibleLine(value, index) {
  return `[${index}] ${JSON.stringify(value)}`;
}

function cardSvg(slots) {
  const texts = slots.map((value, row) => {
    const line = visibleLine(value, row);
    if (line.length > COLUMNS) throw new Error(`Rendered row ${row} exceeds conservative width: ${line.length} > ${COLUMNS}`);
    const y = PAD_Y + ((row + 1) * CHARACTER_HEIGHT_PX) - 3;
    return `<text x="${PAD_X}" y="${y}">${xmlEscape(line)}</text>`;
  }).join('');

  return Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${VIEWPORT_WIDTH}" height="${VIEWPORT_HEIGHT}" viewBox="0 0 ${VIEWPORT_WIDTH} ${VIEWPORT_HEIGHT}">` +
    `<rect width="100%" height="100%" fill="white"/>` +
    `<g xml:space="preserve" fill="black" font-family="DejaVu Sans Mono, monospace" font-size="${FONT_SIZE_PX}px">${texts}</g>` +
    `</svg>`,
    'utf8'
  );
}

function sha256(bytes) {
  return crypto.createHash('sha256').update(bytes).digest('hex');
}

function manifestPath(commitSha) {
  return path.join(manifestRoot, `${validateCommitSha(commitSha)}.json`);
}

async function writeCard(slots) {
  const fileName = randomCardName();
  const filePath = path.join(readingRoom, fileName);
  const png = await sharp(cardSvg(slots)).png({ compressionLevel: 9 }).toBuffer();
  fs.writeFileSync(filePath, png);
  return { fileName, pngSha256: sha256(png) };
}

function removeGeneratedCards() {
  if (!fs.existsSync(readingRoom)) return;
  for (const name of fs.readdirSync(readingRoom)) {
    if (CARD_NAME_RE.test(name)) fs.rmSync(path.join(readingRoom, name), { force: true });
  }
}

function removeLegacyCanonical() {
  const legacy = path.join(readingRoom, DOC_NAME);
  if (fs.existsSync(legacy)) fs.rmSync(legacy, { force: true });
}

function removeActiveChallenges() {
  if (!fs.existsSync(readingRoom)) return;
  for (const name of fs.readdirSync(readingRoom)) {
    if (ACTIVE_RE.test(name)) fs.rmSync(path.join(readingRoom, name), { force: true });
  }
}

async function buildChallenge(commitSha) {
  const sha = validateCommitSha(commitSha);
  const full = projectAgents();
  const canonical = full.items;
  const shuffled = shuffle(canonical);

  if (canonical.length % ROWS !== 0) throw new Error('Canonical item count must fill whole ordered cards');
  const referenceCardCount = canonical.length / ROWS;
  const referenceGroups = [];
  for (let i = 0; i < canonical.length; i += ROWS) {
    referenceGroups.push(canonical.slice(i, i + ROWS));
  }

  const pairs = canonical.map((ordered, i) => ({ ordered, shuffled: shuffled[i] }));
  const pairsPerMixedCard = ROWS / 2;
  const mixedCardCount = referenceCardCount * 2;
  const mixedGroups = [];
  for (let i = 0; i < pairs.length; i += pairsPerMixedCard) {
    mixedGroups.push(pairs.slice(i, i + pairsPerMixedCard));
  }
  if (mixedGroups.length !== mixedCardCount) {
    throw new Error(`Expected ${mixedCardCount} mixed cards, got ${mixedGroups.length}`);
  }

  fs.mkdirSync(readingRoom, { recursive: true });
  removeGeneratedCards();
  removeLegacyCanonical();
  removeActiveChallenges();

  const cards = {};

  for (const group of referenceGroups) {
    const { fileName, pngSha256 } = await writeCard(group);
    cards[fileName] = {
      role: 'ordered-reference',
      slots: group,
      placement_slots: Array(group.length).fill(false),
      png_sha256: pngSha256
    };
  }

  for (const group of mixedGroups) {
    const orderedParity = crypto.randomInt(0, 2) === 0 ? 'odd' : 'even';
    const { slots, placementSlots } = buildMixedSlots(group, orderedParity);
    const { fileName, pngSha256 } = await writeCard(slots);
    cards[fileName] = {
      role: 'mixed',
      ordered_parity: orderedParity,
      slots,
      placement_slots: placementSlots,
      png_sha256: pngSha256
    };
  }

  fs.mkdirSync(manifestRoot, { recursive: true });
  writeJson(manifestPath(sha), {
    challenge: 'agents-png-locator-v2',
    challenge_commit_sha: sha,
    source_blob_sha: full.source_blob_sha,
    item_count: canonical.length,
    logical_copies: { ordered: 2, shuffled: 1 },
    cards
  });

  const challenge = {
    challenge: 'agents-png-locator-v2',
    source_blob_sha: full.source_blob_sha,
    handshake: {
      protocol: 'This challenge is a handshake. Issuing the challenge is the request leg; committing a completed locator is the response leg; a verifier PASS is the acknowledgement that closes the handshake.',
      no_end_of_turn: 'Do not end the turn while this handshake remains open. Continue the read, solve, submit, and evaluate sequence until the verifier returns PASS, unless live evidence establishes an external blocker that makes continuation impossible.',
      completion_condition: 'The handshake is complete only after the verifier returns PASS for the active challenge. A plan, partial locator, submission without PASS, or statement of completion does not close the handshake.'
    },
    viewport: {
      width_px: VIEWPORT_WIDTH,
      height_px: VIEWPORT_HEIGHT,
      character_height_px: CHARACTER_HEIGHT_PX,
      conservative_character_width_px: CONSERVATIVE_CHARACTER_WIDTH_PX,
      rows: ROWS,
      columns: COLUMNS,
      cpx: CPX
    },
    card_model: {
      logical_ordered_copies: 2,
      logical_shuffled_copies: 1,
      dense_ordered_reference_cards: referenceGroups.length,
      mixed_interleave_cards: mixedGroups.length,
      total_cards: Object.keys(cards).length,
      filenames_are_random: true,
      collection_is_mixed: true,
      interleave_rule: 'On every mixed card, counting the first visible row as 1, the ordered-array copy occupies only one parity (all odd rows or all even rows). The shuffled-array copy occupies the opposite parity.',
      placement_rule: 'Only shuffled rows on mixed cards are legal placement sources. Dense ordered-reference rows and ordered-parity rows on mixed cards are reference-only.'
    },
    answer_format: 'locator[n] = [png_filename, zero_based_array_index_in_that_png]',
    item_count: canonical.length,
    locator: Array(canonical.length).fill(null)
  };

  const active = pathsFor(sha).active;
  writeJson(active, challenge);
  console.log(`[live-ground-truth] issued ${path.basename(active)} with ${Object.keys(cards).length} random PNG cards (${referenceGroups.length} dense ordered-reference, ${mixedGroups.length} ordered+shuffled interleave)`);
  console.log(`[live-ground-truth] logical corpus = ordered x2 + shuffled x1; Cpx=${CPX}; items=${canonical.length}`);
  return challenge;
}

function parseChallengePath(challengePath) {
  const normalized = challengePath.replace(/\\/g, '/');
  const prefix = 'ChatMachines/GeminiSupervisor/live-ground-truth/reading-room/';
  if (!normalized.startsWith(prefix)) throw new Error('Challenge path is outside the reading room');
  const name = path.posix.basename(normalized);
  const match = ACTIVE_RE.exec(name);
  if (!match) throw new Error(`Not an active Live Ground Truth challenge: ${name}`);
  return { challengeCommitSha: match[1].toLowerCase() };
}

function cardInventory(challengeCommitSha) {
  const filePath = manifestPath(challengeCommitSha);
  if (!fs.existsSync(filePath)) throw new Error(`Challenge manifest not restored: ${filePath}`);
  const manifest = readJson(filePath);
  if (!manifest || manifest.challenge !== 'agents-png-locator-v2' || !manifest.cards) {
    throw new Error('Invalid challenge manifest');
  }

  const inventory = new Map();
  for (const [name, card] of Object.entries(manifest.cards)) {
    if (!CARD_NAME_RE.test(name) || !Array.isArray(card.slots) || !Array.isArray(card.placement_slots)) {
      throw new Error(`Invalid manifest card: ${name}`);
    }
    if (card.slots.length !== card.placement_slots.length) throw new Error(`Placement mask mismatch: ${name}`);

    const pngPath = path.join(readingRoom, name);
    if (!fs.existsSync(pngPath)) throw new Error(`Challenge PNG is missing: ${name}`);
    const actualSha = sha256(fs.readFileSync(pngPath));
    if (actualSha !== card.png_sha256) throw new Error(`Challenge PNG was modified: ${name}`);

    inventory.set(name, {
      slots: card.slots,
      placementSlots: card.placement_slots
    });
  }
  return { manifest, inventory };
}

function verifyLocator(locator, canonical, inventory) {
  if (!Array.isArray(locator) || locator.length !== canonical.length) return false;

  let legalPlacementCount = 0;
  for (const card of inventory.values()) {
    legalPlacementCount += card.placementSlots.filter(Boolean).length;
  }
  if (legalPlacementCount !== canonical.length) return false;

  const used = new Set();
  for (let n = 0; n < canonical.length; n++) {
    const loc = locator[n];
    if (!Array.isArray(loc) || loc.length !== 2) return false;
    const [fileName, arrayIndex] = loc;
    if (typeof fileName !== 'string' || !CARD_NAME_RE.test(fileName)) return false;
    if (!Number.isInteger(arrayIndex) || arrayIndex < 0) return false;

    const card = inventory.get(fileName);
    if (!card || arrayIndex >= card.slots.length || card.placementSlots[arrayIndex] !== true) return false;

    const unique = `${fileName}:${arrayIndex}`;
    if (used.has(unique)) return false;
    used.add(unique);

    if (!isDeepStrictEqual(card.slots[arrayIndex], canonical[n])) return false;
  }

  return used.size === canonical.length;
}

async function verify(challengePath, evaluationCommitSha) {
  const { challengeCommitSha } = parseChallengePath(challengePath);
  const evaluationSha = validateCommitSha(evaluationCommitSha);
  const resultPaths = pathsFor(evaluationSha);
  const absoluteChallenge = path.join(repoRoot, challengePath);
  if (!fs.existsSync(absoluteChallenge)) throw new Error(`Challenge file not found: ${challengePath}`);

  const full = projectAgents();
  const submitted = readJson(absoluteChallenge);
  const { manifest, inventory } = cardInventory(challengeCommitSha);
  const pass =
    manifest.source_blob_sha === full.source_blob_sha &&
    manifest.item_count === full.items.length &&
    submitted?.challenge === 'agents-png-locator-v2' &&
    submitted?.source_blob_sha === full.source_blob_sha &&
    verifyLocator(submitted.locator, full.items, inventory);

  fs.rmSync(absoluteChallenge, { force: true });
  removeGeneratedCards();

  if (pass) {
    writeJson(resultPaths.pass, {
      status: 'PASS',
      source_blob_sha: full.source_blob_sha,
      item_count: full.items.length
    });
    console.log(`[live-ground-truth] PASS ${evaluationSha}`);
    return true;
  }

  writeJson(resultPaths.failed, { status: 'FAILED' });
  await buildChallenge(evaluationSha);
  console.log(`[live-ground-truth] FAILED ${evaluationSha}; issued fresh PNG challenge`);
  return false;
}

async function issue(commitSha) {
  const request = readJson(requestPath);
  if (request['Agents.md'] !== true) throw new Error('read-request.json must contain "Agents.md": true');
  await buildChallenge(commitSha);
}

async function main() {
  const mode = process.argv[2];
  if (mode === 'issue') {
    await issue(process.argv[3]);
    return;
  }
  if (mode === 'verify') {
    const ok = await verify(process.argv[3], process.argv[4]);
    process.exitCode = ok ? 0 : 2;
    return;
  }
  throw new Error('Usage: live-ground-truth-reading-room.js issue <commit-sha> | verify <challenge-path> <evaluation-commit-sha>');
}

main().catch((error) => {
  console.error(`[live-ground-truth] ${error.stack || error.message}`);
  process.exitCode = 1;
});
